    "explain": "Nipah virus อยู่ใน family Paramyxoviridae genus Henipavirus มีค้างคาวผลไม้ Pteropus เป็นแหล่งรังโรคตามธรรมชาติ และสุกรเป็น amplifier host การระบาดครั้งแรกที่มาเลเซียปี 1998 ถึง 1999 ถูกเข้าใจผิดว่าเป็นไข้สมองอักเสบเจอี เพราะมีไข้ อาการทางระบบหายใจและระบบประสาทคล้ายกัน ส่วนที่ฟิลิปปินส์ปี 2014 คนติดจากการจับม้าป่วยหรือกินเนื้อม้า ปัจจุบันยังไม่มีวัคซีนและยาต้านไวรัสจำเพาะ จึงรักษาแบบประคับประคอง\n\n❌ ทำไมข้ออื่นผิด\n— Filoviridae คือ family ของ Ebola virus ไม่ใช่ Nipah\n— ยังไม่มีวัคซีน Nipah ที่ใช้ในคน\n— อาการของ Nipah เทียบกับไข้สมองอักเสบเจอี ไม่ใช่ rabies\n— มีรายงานคนติด Nipah ผ่านม้าป่วยที่ฟิลิปปินส์ปี 2014\n\n💡 Nipah: Paramyxo ค้างคาวเป็นรังโรค สุกรขยายเชื้อ อาการคล้าย JE ม้าที่ฟิลิปปินส์ และยังไม่มีวัคซีน",
    "source": "Zoonosis Mid 86(1).pdf หน้า 5",
