    "explain": "Ebola virus disease หรือชื่อเดิม Ebola haemorrhagic fever เป็นโรคติดต่อรุนแรงในคนและ non-human primates เช่น กอริลลาและชิมแปนซี อัตราป่วยตายสูงราวร้อยละ 50 ขึ้นไป พบส่วนใหญ่ในแอฟริกา ค้างคาวเป็นแหล่งรังโรคที่เชื้อหมุนเวียนอยู่โดยไม่แสดงอาการ ส่วนสุกรที่ฟิลิปปินส์ตรวจพบแอนติบอดี และสุนัขกับแมวตรวจพบเชื้อได้แต่ไม่มีอาการชัดเจน\n\n❌ ทำไมข้ออื่นผิด\n— สุกรกับม้าที่ป่วยแล้วแพร่สู่คน เป็นภาพของ Nipah และ Hendra virus\n— นกกับม้าที่มียุงรำคาญเป็นพาหะ เป็นภาพของ West Nile virus\n— โค แกะ และแพะที่แท้งจำนวนมาก เป็นภาพของ Rift Valley fever\n— สุนัขและแมวตรวจพบการติดเชื้อ Ebola ได้ แต่ไม่แสดงอาการชัดเจน\n\n💡 Ebola ป่วยหนักในคนกับลิงใหญ่ ค้างคาวเป็นเพียงที่เก็บเชื้อ",
