    "answer": 2,
    "explain": "soil-borne zoonotic parasite คือปรสิตที่ระยะติดต่อปนเปื้อนอยู่ในดินแล้วเข้าสู่คนทางปากหรือไชผ่านผิวหนัง ฝั่ง protozoa ได้แก่ Toxoplasma gondii ที่มากับ oocyst ในมูลแมว Giardia duodenalis, Cryptosporidium parvum และ Sarcocystis ฝั่งหนอนพยาธิได้แก่ hookworm (Ancylostoma spp.) Toxocara, Strongyloides, Ascaris, Baylisascaris และ Echinococcus ชุดที่ถูกต้องจึงต้องไม่มีเชื้อที่อาศัยพาหะปนอยู่เลย\n\n❌ ทำไมข้ออื่นผิด\n— ชุดที่มี Leishmania infantum ผิด เพราะ Leishmania ติดต่อโดย sandfly จัดเป็น vector-borne\n— ชุดที่มี Trypanosoma cruzi ผิด เพราะ Trypanosoma ติดต่อโดยแมลงดูดเลือด จัดเป็น vector-borne\n— ชุดที่มี Dirofilaria immitis ผิด เพราะ heartworm มียุงเป็นพาหะ จัดเป็น vector-borne\n— ชุดที่มี Babesia ผิด เพราะ Babesia มีเห็บเป็นพาหะ จัดเป็น vector-borne\n\n💡 แยกให้ออกว่าเชื้อรอคนอยู่ในดิน หรือต้องมีแมลงหรือเห็บมากัดก่อนจึงจะติด",
    "source": "Zoonosis Mid 86(1).pdf หน้า 17",
