    "explain": "vector-borne parasitic zoonosis คือปรสิตที่ต้องมีแมลงหรือสัตว์ขาข้อเป็นพาหะนำจากสัตว์สู่คน ได้แก่ heartworm (Dirofilaria immitis) และ filaria worm อื่น เช่น Brugia ที่มียุงเป็นพาหะ Leishmania infantum ที่มี sandfly เป็นพาหะ Trypanosoma ที่มีแมลงดูดเลือดเป็นพาหะ Babesia ที่มีเห็บเป็นพาหะ และ Plasmodium ที่มียุงเป็นพาหะ\n\n❌ ทำไมข้ออื่นผิด\n— ชุดที่มี Toxocara canis ผิด เพราะคนติดจากการกินไข่ที่ปนเปื้อนดิน จัดเป็น soil-borne\n— ชุดที่มี Giardia duodenalis ผิด เพราะคนติดจากการกิน cyst ที่ปนเปื้อนน้ำ อาหาร และดิน\n— ชุดที่มี Cryptosporidium parvum ผิด เพราะคนติดจากการกิน oocyst ที่ปนเปื้อนน้ำ อาหาร และดิน\n— ชุดที่มี Ancylostoma spp. ผิด เพราะตัวอ่อนในดินไชผ่านผิวหนัง จัดเป็น soil-borne\n\n💡 ถ้าต้องมีสัตว์ขาข้อกัดก่อนจึงจะติด คือกลุ่ม vector-borne",
