    "explain": "T. gondii ติดคนได้จากการกิน tissue cyst ในเนื้อสัตว์ที่ปรุงไม่สุก การกิน oocyst ที่ปนเปื้อนมาจากมูลแมว การติดผ่านรกจากแม่สู่ทารก และการปลูกถ่ายอวัยวะที่มี tissue cyst จากผู้ให้ที่ติดเชื้อ\n\n❌ ทำไมข้ออื่นผิด\n— ละอองฝอยจากผู้ติดเชื้อไม่มีระยะติดต่อของ T. gondii ออกมา\n— คนไม่ขับ oocyst เพราะวงจรแบบอาศัยเพศเกิดในลำไส้ของสัตว์ตระกูลแมวเท่านั้น การใช้ห้องน้ำร่วมกันจึงไม่ติด\n— น้ำลายไม่ใช่ทางติดต่อของ T. gondii\n— T. gondii ไม่มีแมลงเป็นพาหะ ยุงจึงไม่นำเชื้อ\n\n💡 นอกจากกินและผ่านรก ให้นึกถึงการปลูกถ่ายอวัยวะ",
