    "explain": "เมื่อคนกินเนื้อหมูที่มี cysticercus cellulosae คนเป็นโฮสต์สุดท้าย และมีตัวตืดเต็มวัยในลำไส้เล็กเรียกว่า taeniasis แต่เมื่อคนกลืนไข่ที่หลุดมากับปล้องสุกในอุจจาระ คนจะอยู่ในฐานะเดียวกับหมู คือเป็นโฮสต์กลาง ตัวอ่อนจากไข่เจริญเป็น cysticercus ในเนื้อเยื่อ เรียกว่า cysticercosis และอาจเดินทางผิดที่ไปยังระบบประสาทส่วนกลาง เกิดเป็น neurocysticercosis ซึ่งเป็นภาวะที่อันตรายที่สุดของพยาธิตัวนี้\n\n❌ ทำไมข้ออื่นผิด\n— ตัวเต็มวัยในลำไส้เล็กเกิดจากการกินซิสต์ในเนื้อหมู ไม่ใช่การกลืนไข่\n— รอยทางคดเคี้ยวใต้ผิวหนังเกิดจากตัวอ่อน L3 ของพยาธิปากขอที่ไชผิวหนัง\n— ไข่ของ T. solium ติดสู่คนได้ และเป็นทางที่ทำให้เกิด cysticercosis ในคน\n— paratenic host และการไปที่ตาเป็นลักษณะของ Toxocara ไม่ใช่ตัวตืด\n\n💡 กินเนื้อที่มีซิสต์ได้ตัวตืด กลืนไข่ได้ซิสต์ และซิสต์ที่ไปสมองคือ neurocysticercosis",
