    "explain": "Taenia saginata มีคนเป็นโฮสต์สุดท้ายและโคเป็นโฮสต์กลาง ตัวเต็มวัยในลำไส้เล็กของคนรักษาได้ด้วยยาถ่ายตัวตืด praziquantel แต่ cysticercus bovis ที่ฝังอยู่ในกล้ามเนื้อโคไม่มียารักษา เพราะยากระจายเข้าไปถึงซิสต์ในเนื้อเยื่อได้ยาก และโคที่มีซิสต์ก็มักไม่แสดงอาการ การป้องกันจึงอยู่ที่การปรุงเนื้อให้สุกทุกครั้ง ร่วมกับการสุขาภิบาลที่ไม่ให้อุจจาระคนปนเปื้อนแปลงหญ้าที่โคกิน ซิสต์ในเนื้อมีขนาดมองเห็นได้ด้วยตาเปล่า\n\n❌ ทำไมข้ออื่นผิด\n— ซิสต์ในกล้ามเนื้อโคไม่มียารักษา การถ่ายพยาธิโคก่อนส่งโรงฆ่าจึงไม่ได้แก้ปัญหานี้\n— pyrantel ออกฤทธิ์กับพยาธิตัวกลม ไม่ใช่ยาหลักของตัวตืด\n— วัคซีนไม่ใช่เครื่องมือควบคุมหลักของโรคนี้ และการตรวจซากกับการปรุงเนื้อให้สุกยังจำเป็นเสมอ\n— น้ำมะนาวหรือเกลือไม่ได้ทำลายซิสต์ ความร้อนจากการปรุงสุกคือตัวทำลาย\n\n💡 ตัวตืดในคนมียา ซิสต์ในโคไม่มียา ทางป้องกันจึงเป็นความร้อนและสุขาภิบาล",
