    "explain": "Echinococcus มีสุนัขเป็นโฮสต์สุดท้ายซึ่งมีตัวตืดเต็มวัยอยู่ในลำไส้ และมีสัตว์เคี้ยวเอื้อง เช่น แกะ เป็นโฮสต์กลาง คนติดจากการกลืนไข่ที่ออกมากับอุจจาระสุนัข แล้วเกิดถุงน้ำ hydatid ในอวัยวะ การควบคุมจึงเน้นถ่ายพยาธิสุนัขด้วย praziquantel ซึ่งกำจัดตัวเต็มวัยได้ดี ประเทศไทยไม่ใช่พื้นที่ที่มีโรคนี้เป็นโรคประจำถิ่น โรคนี้พบได้ทางแถบยุโรปและพื้นที่เลี้ยงแกะ\n\n❌ ทำไมข้ออื่นผิด\n— สุกรเป็นได้เพียงโฮสต์กลาง ไม่ใช่โฮสต์สุดท้ายของ Echinococcus\n— pyrantel ออกฤทธิ์กับพยาธิตัวกลม ใช้กำจัดตัวตืดไม่ได้\n— โรคนี้ไม่ใช่โรคประจำถิ่นของไทย รวมถึงภาคอีสาน\n— แกะเป็นโฮสต์กลาง และคนติดจากการกลืนไข่จากอุจจาระสุนัข ไม่ใช่กินซิสต์ในเนื้อ\n\n💡 Echinococcus ตัวตืดอยู่ในสุนัข ถุงน้ำอยู่ในโฮสต์กลาง และไม่ใช่โรคประจำถิ่นของไทย",
