    "q": "เหตุใดสุนัขที่มีพยาธิปากขอจำนวนมากจึงถ่ายอุจจาระสีดำคล้ำและอาจตายจากภาวะโลหิตจาง",
    "options": [
      "ตัวอ่อนไชผ่านผนังลำไส้ไปอุดหลอดเลือดในตับ ทำให้ตับวายและเลือดแข็งตัวผิดปกติ",
      "ตัวเต็มวัยหลั่งสารพิษที่ทำลายไขกระดูกโดยตรง จึงสร้างเม็ดเลือดแดงไม่ได้",
      "ตัวเต็มวัยดูดเลือด และหลั่ง anticoagulant peptide กับ platelet inhibitor เลือดจึงไหลไม่หยุด",
      "ไข่พยาธิอุดตันลำไส้ใหญ่จนเกิดแผลและลำไส้แตก เลือดจึงออกในช่องท้อง",
      "ตัวเต็มวัยกระตุ้น factor VII และ X จนเกิดลิ่มเลือดทั่วร่างกายและเกล็ดเลือดหมด"
    ],
    "answer": 2,
    "explain": "ตัวเต็มวัยของพยาธิปากขอเกาะผนังลำไส้เล็กแล้วดูดเลือด พร้อมหลั่ง anticoagulant peptide ที่ยับยั้ง factor VII และ factor X และหลั่ง hookworm platelet inhibitor ที่ยับยั้งการรวมตัวของเกล็ดเลือด ตำแหน่งที่พยาธิเกาะจึงเลือดออกไม่หยุด สุนัขเสียเลือดเรื้อรังจนเกิดโลหิตจางแบบขาดธาตุเหล็ก อุจจาระมีเลือดที่ถูกย่อยแล้วจึงเป็นสีดำคล้ำเหมือนถ่าน และในรายรุนแรงตายจากโลหิตจางได้ ผิวของตัวพยาธิยังมี proteinase inhibitor ที่ยับยั้ง chymotrypsin, pancreatic elastase และ neutrophil elastase ตัวพยาธิจึงไม่ถูกโฮสต์ทำลาย แต่ยังแพ้ยาถ่ายพยาธิ\n\n❌ ทำไมข้ออื่นผิด\n— ตัวอ่อนพยาธิปากขอไม่ได้ไปอุดหลอดเลือดในตับ และปัญหาคือเลือดไม่แข็งตัว\n— โลหิตจางเกิดจากการเสียเลือดทางลำไส้ ไม่ใช่สารพิษทำลายไขกระดูก\n— ไข่ไม่ได้อุดตันลำไส้ใหญ่ และเลือดออกในลำไส้ ไม่ใช่ในช่องท้อง\n— สารของพยาธิยับยั้ง factor VII และ X จึงทำให้เลือดไม่แข็งตัว ไม่ใช่กระตุ้นให้เกิดลิ่มเลือด\n\n💡 พยาธิปากขอฆ่าได้ด้วยการเสียเลือด เพราะมันปิดทุกทางที่เลือดจะหยุด",
