    "answer": 0,
    "explain": "Trichuris vulpis มีวงจรชีวิตตรง ไม่มีโฮสต์กลาง และตัวอ่อนไม่ไชไปตามอวัยวะ สุนัขติดจากการกลืนไข่ที่มีตัวอ่อน L1 จากสิ่งแวดล้อม ตัวเต็มวัยอาศัยที่ cecum และลำไส้ใหญ่ เมื่อมีจำนวนมากทำให้ไส้ตันอักเสบ (typhlitis) และท้องเสียมีมูกปนเลือด ระยะตั้งแต่ติดจนพบไข่นานราว 3 เดือน ซึ่งยาวกว่าพยาธิปากขอ โปรแกรมถ่ายพยาธิลูกสุนัขจึงถ่ายซ้ำตอนอายุ 6 เดือน และสุนัขที่เสี่ยงควรถ่ายพยาธิทุกราว 3 เดือนร่วมกับรักษาความสะอาดของพื้นที่ ยาที่ได้ผลมีทั้ง milbemycin oxime ซึ่งอยู่ในกลุ่ม macrocyclic lactone และ fenbendazole ส่วน pyrantel ไม่ได้ผลกับพยาธิแส้ม้า\n\n❌ ทำไมข้ออื่นผิด\n— พยาธิแส้ม้าไม่มีโฮสต์กลาง และระยะก่อนพบไข่ยาวราว 3 เดือน ไม่ใช่ 3 สัปดาห์\n— การไชผิวหนังและการติดผ่านน้ำนมเป็นลักษณะของพยาธิปากขอ\n— ตัวเต็มวัยของพยาธิแส้ม้าอยู่ที่ cecum และลำไส้ใหญ่ การดูดเลือดในลำไส้เล็กเป็นของพยาธิปากขอ\n— pyrantel ใช้ไม่ได้ผลกับพยาธิแส้ม้า\n\n💡 แส้ม้าวงจรตรง รอบละราว 3 เดือน และ pyrantel ไม่ครอบคลุม",
