    "answer": 1,
    "explain": "Thelazia callipaeda เป็นพยาธินัยน์ตาของสุนัข แมว และคน มีแมลงหวี่ที่ตอมน้ำตาเป็นพาหะ ในไทยมีรายงานในสัตว์จากภาคเหนือมาตั้งแต่ปี 2008 และมีเคสคนที่พบพยาธิในช่องหน้าลูกตา ซึ่งแพทย์ที่โรงพยาบาลในจังหวัดอุตรดิตถ์เป็นผู้รายงาน รายงานนี้ระบุชนิดโดยไม่ได้ยืนยันด้วยอณูชีววิทยา จึงยังมีข้อสงสัยว่าอาจเป็น Brugia pahangi ซึ่งเคยพบในลูกตาของเด็กไทยเช่นกัน\n\n❌ ทำไมข้ออื่นผิด\n— เชียงใหม่เป็นพื้นที่ที่มีรายงาน Thelazia ในสุนัข ไม่ใช่ที่มาของรายงานผู้ป่วยรายนี้\n— ร้อยเอ็ดไม่ใช่ที่มาของรายงานผู้ป่วยรายนี้\n— สระบุรีไม่ใช่ที่มาของรายงานผู้ป่วยรายนี้\n— นครปฐมไม่ใช่ที่มาของรายงานผู้ป่วยรายนี้\n\n💡 Thelazia ในไทยอยู่ทางภาคเหนือ และเคสคนในช่องหน้าลูกตารายงานจากอุตรดิตถ์",
    "source": "Zoonosis Mid 86.pdf หน้า 13",
    "sourceType": "student-compilation",
    "verified": "Zoonosis Mid 86.pdf หน้า 13 (= Zoonosis Mid 86(1).pdf หน้า 30) บันทึกหลังสอบที่มุมขวาบนว่ามีข้อเรื่องเคสในไทยของ Thelazia (ติ๊กไว้พร้อม D. repens และ B. pahangi) จำโจทย์ไม่ได้แต่ให้อ่านว่าเจอที่จังหวัดไหนและผู้ป่วยคือใคร (= ซูสุขติ mid น.13; ข้อ 18 หน้าเดียวกันบันทึกเคสในสุนัขที่เชียงใหม่); ถามซ้ำใน Zoonosis mid TJ เฉลย.pdf น.27 ข้อ 21 (เฉลย ข. จังหวัดอุตรดิตถ์ ตัวเลือกห้าจังหวัดชุดเดียวกับข้อนี้; หัวบล็อกไม่ได้ระบุที่มา และข้อ 21 ไม่อยู่ใน 19 ข้อของบันทึกหลังสอบ) ซ้ำใน Zoonosis Mid 86(1).pdf หน้า 63 (สำเนาหน้า TJ); ตรวจกับ gwgmq6oGOWc [65:11-67:32] ได้แก่ [65:45] (รายงานจากภาคเหนือตั้งแต่ 2008) [66:06]-[66:28] (ผู้ป่วยทั่วโลกรวมถึงไทย intraocular infestation) [66:43]-[66:55] (ไม่ได้ยืนยันด้วยโมเลกุล อาจเป็น B. pahangi ผู้เขียนเป็นแพทย์โรงพยาบาลที่อุตรดิตถ์) และ [67:18]-[67:32] (ผู้ป่วยในไทยทั้งเด็กและผู้ใหญ่)",
