    "answer": 4,
    "explain": "โคโรนาไวรัสแบ่งเป็น 4 genus คือ Alpha, Beta, Gamma และ Delta กลุ่มที่ก่อการระบาดใหญ่ในคนคือ Betacoronavirus ซึ่งรวม SARS-CoV, MERS-CoV และ SARS-CoV-2 ส่วน Alphacoronavirus มีเชื้อในสัตว์หลายชนิดที่เด่นด้านโรคทางเดินอาหาร เช่น PEDV และ TGEV ในสุกร รวมถึง FIPV ในแมว และ HCoV-229E ที่ทำให้เป็นหวัดในคน Gammacoronavirus พบในสัตว์ปีกและสัตว์น้ำ เช่น โลมา ส่วน Deltacoronavirus มีเชื้ออย่าง PDCoV ที่ทำให้ลูกสุกรท้องเสีย\n\n❌ ทำไมข้ออื่นผิด\n— SARS-CoV-2 และ MERS-CoV อยู่ใน Beta ส่วนโรคทางเดินอาหารในสัตว์เป็นลักษณะเด่นของ Alpha\n— เชื้อที่ก่อโรคในโลมาอยู่ใน Gamma ไม่ใช่ Delta\n— โคโรนาไวรัสมี 4 genus ไม่ใช่ 3\n— Alpha เด่นด้านโรคทางเดินอาหาร ไม่ใช่โรคระบบประสาท\n\n💡 Beta ระบาดในคน Alpha ท้องเสียในสัตว์ Gamma นกและโลมา รวม Delta เป็น 4 genus",
