    "explain": "SARS-CoV มีต้นกำเนิดจากค้างคาว งานศึกษาในค้างคาวมงกุฎสกุล Rhinolophus พบไวรัสที่ลำดับพันธุกรรมใกล้เคียงกับเชื้อในผู้ป่วยมาก ส่วนชะมดที่ตรวจพบเชื้อในตลาดค้าสัตว์ป่ามีชีวิตทางตอนใต้ของจีนเป็นโฮสต์กึ่งกลางที่ส่งเชื้อต่อสู่คน รูปแบบเดียวกันนี้เห็นใน MERS-CoV ที่มีต้นกำเนิดจากค้างคาวและมีอูฐเป็นโฮสต์กึ่งกลาง\n\n❌ ทำไมข้ออื่นผิด\n— ชะมดเป็นโฮสต์กึ่งกลางของ SARS-CoV ไม่ใช่ต้นกำเนิด\n— อูฐเป็นโฮสต์กึ่งกลางของ MERS-CoV\n— ตัวนิ่มเป็นสัตว์ที่ถูกศึกษาในฐานะโฮสต์ที่อาจเกี่ยวข้องกับ SARS-CoV-2\n— หนูเป็นต้นกำเนิดของ HCoV-OC43 ไม่ใช่ SARS-CoV\n\n💡 ต้นกำเนิดคือค้างคาว ส่วนตัวกลางของ SARS คือชะมด",
