    "answer": 3,
    "explain": "antigenic drift เกิดจาก point mutation ที่สะสมไปเรื่อย ๆ เพราะไวรัสไข้หวัดใหญ่เป็น RNA ไวรัสที่ไม่มีระบบตรวจแก้ไขการคัดลอก ส่วน antigenic shift เกิดจาก reassortment เมื่อไวรัสต่างสายพันธุ์ติดเซลล์เดียวกันแล้วสลับท่อนยีน ทั้งสองกลไกเป็นคุณสมบัติของไวรัสไข้หวัดใหญ่สายพันธุ์ A จึงเกิดได้ทั้งใน LPAI และ HPAI เช่น HPAI H5N8 ผสมกับ LPAI ที่มี N2 ในนกอเมริกาแล้วกลายเป็น H5N2 และ LPAI สาย H5 หรือ H7 ที่กลายพันธุ์ตรง cleavage site ก็เปลี่ยนเป็น HPAI ได้\n\n❌ ทำไมข้ออื่นผิด\n— LPAI ก็มี point mutation และ reassortment เช่นกัน\n— HPAI ก็เกิด drift และ reassortment ได้ เช่น H5N8 ที่กลายเป็น H5N2\n— ทั้งสองกลไกไม่ได้แยกตามความรุนแรงของเชื้อ\n— ทั้งสองกลไกเกิดในไวรัสไข้หวัดนกด้วย และเป็นที่มาของสายพันธุ์ใหม่ในสัตว์ปีก\n\n💡 drift และ shift ไม่ได้เลือกความรุนแรง เกิดได้ทั้ง LPAI และ HPAI",
