    "answer": 4,
    "explain": "hemagglutinin ของไวรัสไข้หวัดนกชอบจับกับตัวรับ sialic acid ที่เชื่อมกับ galactose แบบ α2,3 ซึ่งมีมากบนเซลล์ของสัตว์ปีก ส่วนไวรัสของสัตว์เลี้ยงลูกด้วยนมชอบแบบ α2,6 การข้ามระหว่างสองกลุ่มจึงเกิดได้ยาก ยกเว้นในโฮสต์ที่มีตัวรับทั้งสองชนิด เช่น สุกรและนกกระทา รวมถึงเต้านมของโคนมที่ทำให้ H5N1 clade 2.3.4.4b ติดโคนมและขับออกทางน้ำนมได้\n\n❌ ทำไมข้ออื่นผิด\n— α2,6 เป็นตัวรับที่ไวรัสของสัตว์เลี้ยงลูกด้วยนมและคนชอบ\n— ACE2 เป็นตัวรับของ SARS-CoV และ SARS-CoV-2\n— DPP4 เป็นตัวรับของ MERS-CoV\n— CD4 เป็นตัวรับของ HIV\n\n💡 นก 2,3 คน 2,6 และหมูมีทั้งสองแบบ",
