    "examScope": "midterm",
    "q": "จากการระบาดของไข้หวัดนก H5N1 ในประเทศไทยช่วงปี 2004 ข้อใดถูกต้องเกี่ยวกับการติดเชื้อในเสือ",
    "options": [
      "เสือติดเชื้อได้แต่ไม่แสดงอาการ จึงเป็นแหล่งรังโรคที่ไม่มีใครสังเกต",
      "เสือที่กินไก่ดิบติดเชื้อแล้วป่วยตายเฉียบพลัน และแพร่จากเสือสู่เสือได้",
      "เสือติดเชื้อจากการถูกยุงกัด และไม่แพร่ต่อระหว่างเสือด้วยกัน",
      "เสือเป็นสัตว์ตระกูลแมวจึงไม่มีตัวรับของไวรัสและติดเชื้อไม่ได้",
      "เสือติดเชื้อจากคนเลี้ยงที่ป่วย และแสดงเพียงอาการไอเล็กน้อย"
    ],
    "answer": 1,
    "explain": "ในช่วงไข้หวัดนกระบาดในไทย มีเคสฟาร์มเสือทางภาคตะวันออกที่ให้เสือกินไก่ดิบซึ่งติดเชื้อ เสือมีเลือดออกที่ตาแล้วตายอย่างรวดเร็ว ตรวจพบ H5N1 และพบว่าเชื้อแพร่จากเสือสู่เสือได้ด้วย หลังเหตุการณ์นี้สวนสัตว์และฟาร์มเสือจึงเปลี่ยนมาให้กินไก่ที่ปรุงสุก สุนัขและแมวบ้านก็ติดเชื้อได้จากการกินซากสัตว์ปีกเช่นกัน\n\n❌ ทำไมข้ออื่นผิด\n— เสือที่ติดเชื้อแสดงอาการรุนแรงและตาย ไม่ได้เป็นพาหะที่ไม่มีอาการ\n— เสือติดจากการกินไก่ดิบที่มีเชื้อ ไม่ใช่ยุงกัด และแพร่ระหว่างเสือได้\n— สัตว์ตระกูลแมวติดเชื้อ H5N1 ได้และป่วยรุนแรง\n— แหล่งเชื้อคือไก่ดิบ ไม่ใช่คนเลี้ยง และอาการรุนแรงถึงตาย\n\n💡 สัตว์ตระกูลแมวที่กินสัตว์ปีกดิบติดเชื้อ H5N1 และป่วยรุนแรง",
    "source": "Zoonosis Mid 86(1).pdf หน้า 36",
    "sourceType": "student-compilation",
    "verified": "Zoonosis Mid 86(1).pdf หน้า 36 พาร์ท AI ข้อ เสือติดก็แสดงอาการนะ (ติดจากกินไก่สด) ในรายการข้อที่บันทึกหลังสอบของรุ่น Vet 84 (หัวกระดาษอยู่ที่หน้า 35); ซ้ำในสำเนารายการเดียวกันที่ไฮไลต์ไว้ในกรอบ AI ของ Zoonosis Mid 86(1).pdf หน้า 8 (= Zoonosis Mid 86.pdf หน้า 7) และตัวอักษรสีเรื่องเสือติดจากการกินไก่ดิบ มีไข้สูง หอบ อาการทางประสาท และตายเฉียบพลัน ใน Zoonosis Mid 86(1).pdf หน้า 9 (= Zoonosis Mid 86.pdf หน้า 8) ซึ่งมุมขวาบนจดว่า ตรง; ถามซ้ำใน Zoonosis mid TJ เฉลย.pdf น.3 ข้อ 8 (บล็อก Influenza virus ที่หัวบล็อกระบุว่าผู้เรียบเรียงแต่งแบบฝึกเอง) ซ้ำใน Zoonosis mid TJ ฝึกทำ.pdf น.3 และ Zoonosis Mid 86(1).pdf หน้า 39 และประเด็นเดียวกันเป็นตัวเลือกใน Zoonosis mid TJ เฉลย.pdf น.5 ข้อ 15; ตรวจกับ oWZEdlLXcpo [85:59-87:27] (ตาเลือดออก ตายเร็ว ผลตรวจ H5N1 ฟาร์มให้ไก่ดิบ และติดต่อจากเสือสู่เสือได้)",
