    "q": "ไวรัส pandemic H1N1 2009 เกิดจากการผสมยีน (reassortment) ของไวรัสที่มีต้นกำเนิดจากแหล่งใด",
    "options": [
      "ไวรัสจากสุกร คน และสัตว์ปีก",
      "ไวรัสจากม้าและสุนัข",
      "ไวรัสไข้หวัดนก H5N1 เพียงแหล่งเดียว",
      "ไวรัสไข้หวัดใหญ่สายพันธุ์ B และ C",
      "ไวรัสจากค้างคาวและอูฐ"
    ],
    "answer": 0,
    "explain": "pandemic H1N1 2009 มีต้นตอจากสุกร ยีนแต่ละท่อนมาจากไวรัสหลายแหล่ง คือไวรัสสุกร ไวรัสคน และไวรัสสัตว์ปีก ที่ผสมกันในสุกรซึ่งเป็น mixing vessel เพราะมีตัวรับทั้ง α2,3 และ α2,6 ไวรัสที่ได้แพร่จากคนสู่คนได้ดีจนระบาดไปหลายประเทศทั่วโลก และย้อนกลับไปติดสุกรได้ด้วย ในไทยหลังปี 2009 ยังพบยีนหลักของ pandemic H1N1 2009 ในไวรัสสุกร\n\n❌ ทำไมข้ออื่นผิด\n— ไวรัสม้าและสุนัขเกี่ยวกับไข้หวัดใหญ่สุนัข H3N8 ไม่ใช่ pandemic H1N1 2009\n— H5N1 เป็นไข้หวัดนก ไม่ใช่ต้นกำเนิดเพียงแหล่งเดียวของไวรัสนี้\n— ไข้หวัดใหญ่สายพันธุ์ B และ C ไม่ได้ผสมยีนกับสายพันธุ์ A\n— ค้างคาวและอูฐเกี่ยวกับโคโรนาไวรัส ไม่ใช่ไข้หวัดใหญ่\n\n💡 pandemic H1N1 2009 มาจากสุกร โดยยีนมาจากสามแหล่งคือ สุกร คน และสัตว์ปีก",
    "source": "Zoonosis Mid 86(1).pdf หน้า 36",
    "sourceType": "student-compilation",
    "verified": "Zoonosis Mid 86(1).pdf หน้า 36 พาร์ท SIV Canine ข้อ pandemic H1N1 2009 ผสมจากใครมาบ้าง (คำตอบที่บันทึกคือ คน สัตว์ปีก หมู) ในรายการข้อที่บันทึกหลังสอบของรุ่น Vet 84 (หัวกระดาษอยู่ที่หน้า 35); ภาพรายการเดียวกันอยู่ใน Zoonosis Mid 86.pdf หน้า 7 (= Zoonosis Mid 86(1).pdf หน้า 8 ซึ่งบรรทัดนี้อยู่ในสำเนารายการเดียวกันแต่ไม่ได้ไฮไลต์); ถามซ้ำใน Zoonosis mid TJ เฉลย.pdf น.4 ข้อ 10 (บล็อก Influenza virus ที่หัวบล็อกระบุว่าผู้เรียบเรียงแต่งแบบฝึกเอง) ซ้ำใน Zoonosis mid TJ ฝึกทำ.pdf น.4 และ Zoonosis Mid 86(1).pdf หน้า 40; บรรทัด NA-SIV มี TRIG cassette และ EU-SIV ให้ยีน M กับ NA อยู่ใน Zoonosis Mid 86.pdf หน้า 8 (= Zoonosis Mid 86(1).pdf หน้า 9) ส่วน 106108 ถามเฉพาะองค์ประกอบของ TRIG; ตรวจกับ oWZEdlLXcpo [22:23-22:42] [61:19-61:43] [119:12-122:54] [124:21-126:48]",
