    "examScope": "midterm",
    "q": "พื้นที่ที่เป็นแหล่งระบาดประจำถิ่นของไข้เหลือง (yellow fever) คือบริเวณใด",
    "options": [
      "เอเชียตะวันออกเฉียงใต้และออสเตรเลีย",
      "อเมริกาเหนือและยุโรปตะวันตก",
      "ตะวันออกกลางและเอเชียใต้",
      "จีน ญี่ปุ่น และคาบสมุทรเกาหลี",
      "แอฟริกา และอเมริกากลางกับอเมริกาใต้"
    ],
    "answer": 4,
    "explain": "ไข้เหลืองเป็นโรคประจำถิ่นในสองภูมิภาค คือแอฟริกา และอเมริกากลางกับอเมริกาใต้ มีลิงเป็นแหล่งรังโรคที่ทำให้ยุงมีเชื้ออยู่ตลอด ทวีปอื่นส่วนใหญ่เป็นเคสที่ติดมาจากการเดินทาง เช่น การระบาดใหญ่ที่แองโกลาปี 2016 โรคนี้ไม่มียารักษาเฉพาะแต่มีวัคซีน จึงแนะนำให้ฉีดก่อนเดินทางเข้าพื้นที่ระบาด ร่วมกับป้องกันยุงกัด\n\n❌ ทำไมข้ออื่นผิด\n— เอเชียตะวันออกเฉียงใต้ถึงออสเตรเลียเป็นพื้นที่ของไข้สมองอักเสบเจอี\n— อเมริกาเหนือเป็นพื้นที่ที่มีเคสเวสต์ไนล์จำนวนมาก ไม่ใช่ไข้เหลือง\n— ตะวันออกกลางและเอเชียใต้ไม่ใช่พื้นที่ประจำถิ่นของไข้เหลือง\n— จีน ญี่ปุ่น และเกาหลีเป็นพื้นที่ที่พบ SFTS\n\n💡 ไข้เหลืองอยู่สองฝั่งมหาสมุทรแอตแลนติก คือแอฟริกากับอเมริกาใต้และอเมริกากลาง",
    "source": "Zoonosis Mid 86(1).pdf หน้า 36",
    "sourceType": "student-compilation",
    "verified": "Zoonosis Mid 86(1).pdf หน้า 36 พาร์ท vector-borne ข้อ yellow fever เจอในแถบไหน (คำตอบที่บันทึกคือ Africa & South/Central America) ในรายการข้อที่บันทึกหลังสอบของรุ่น Vet 84 (หัวกระดาษอยู่ที่หน้า 35); ถามซ้ำใน Zoonosis mid TJ เฉลย.pdf น.9 ข้อ 5 (บล็อก Vector-borne ซึ่งหัวบล็อกไม่ระบุที่มา) ซ้ำใน Zoonosis mid TJ ฝึกทำ.pdf น.9 และ Zoonosis Mid 86(1).pdf หน้า 45; บรรทัด Endemic area: Africa, Central and South America อยู่ในโน้ต Zoonosis Mid 86(1).pdf หน้า 6 (= Zoonosis Mid 86.pdf หน้า 5); ตรวจกับ u_cH2UtCIAg [28:54-31:36] [40:25-40:55] ได้แก่ [29:04-29:11] และ [30:47-30:53] (แอฟริกา อเมริกากลาง อเมริกาใต้) [29:29-29:42] (แองโกลา 2016) และ [31:21-31:36] (ไม่มียารักษา มีวัคซีน ฉีดก่อนเดินทาง)",
