    "explain": "Anatrichosoma เป็นพยาธิตัวกลมกลุ่มเดียวกับพยาธิแส้ม้าและ Capillaria ไข่จึงมีจุกที่ปลาย ตำแหน่งที่พยาธิอาศัยขึ้นกับชนิดของโฮสต์ ในแมวพบพยาธิในชั้นหนังกำพร้าและหนังแท้ของอุ้งเท้าหน้าและอุ้งเท้าหลัง ทำให้เกิด ulcerative pododermatitis ส่วนในลิงและไพรเมตอื่นที่ไม่ใช่คนพบพยาธิในเยื่อเมือกและใต้เยื่อเมือกของโพรงจมูก รายงานแมวรายแรกในประเทศไทยยืนยันด้วยจุลพยาธิวิทยาร่วมกับอณูชีววิทยา ส่วนวงจรชีวิตและทางติดของพยาธินี้ยังไม่เป็นที่เข้าใจดี\n\n❌ ทำไมข้ออื่นผิด\n— ในแมวพยาธิอยู่ที่อุ้งเท้า ไม่ใช่โพรงจมูก ตำแหน่งสองโฮสต์ในข้อนี้สลับกัน\n— ห้องหัวใจขวาและหลอดเลือดแดงปอดเป็นที่อยู่ของ Dirofilaria immitis\n— cecum และลำไส้ใหญ่เป็นที่อยู่ของพยาธิแส้ม้า Trichuris ไม่ใช่ Anatrichosoma ในแมว\n— ท่อน้ำดีในตับเป็นที่อยู่ของพยาธิใบไม้ตับ\n\n💡 Anatrichosoma อยู่ที่อุ้งเท้าในแมว และที่โพรงจมูกในลิง",
