    "explain": "พยาธิปากขอเป็นพยาธิตัวกลม ยาที่ออกฤทธิ์กับพยาธิตัวกลมในลำไส้ใช้ได้ผล เช่น pyrantel และยากลุ่ม macrocyclic lactone อย่าง milbemycin oxime เมื่อตรวจพบพยาธิปากขอแล้วให้ยาถ่ายพยาธิก็จัดการได้ ปัญหาที่พบบ่อยกว่าคือไม่ได้นึกถึงพยาธิปากขอตั้งแต่แรก ลูกสุนัขควรได้ยาถ่ายพยาธิตั้งแต่ครั้งแรกเพราะติดพยาธิปากขอจากแม่ได้ทางน้ำนม\n\n❌ ทำไมข้ออื่นผิด\n— praziquantel เป็นยาของพยาธิตัวตืดและพยาธิใบไม้ ไม่ออกฤทธิ์กับพยาธิปากขอ\n— toltrazuril เป็นยาของโปรโตซัวกลุ่ม coccidia\n— doxycycline เป็นยาปฏิชีวนะ ใช้กับแบคทีเรียรวมถึง Wolbachia ในพยาธิฟิลาเรีย ไม่ได้ฆ่าพยาธิปากขอ\n— metronidazole ใช้กับ Giardia และแบคทีเรียที่ไม่ใช้ออกซิเจน\n\n💡 พยาธิปากขอเป็นพยาธิตัวกลม ยาจึงเป็น pyrantel หรือยากลุ่ม macrocyclic lactone ไม่ใช่ praziquantel",
