    "answer": 3,
    "explain": "Rift Valley fever เป็นโรคประจำถิ่นของแอฟริกามาตั้งแต่พบครั้งแรกในฝูงแกะที่เคนยาปี 1931 การระบาดที่ออกนอกทวีปแอฟริกาครั้งแรกเกิดในปี 2000 ที่ซาอุดีอาระเบียและเยเมนในตะวันออกกลาง โดยมีผู้ป่วยทั้งคนและสัตว์เคี้ยวเอื้อง การระบาดในคนมักตามหลังการแท้งเป็นชุดของสัตว์ในพื้นที่ จึงต้องรายงานและเฝ้าระวังทั้งสัตว์และคนไปพร้อมกัน\n\n❌ ทำไมข้ออื่นผิด\n— อียิปต์และไนจีเรียอยู่ในทวีปแอฟริกา อียิปต์เคยมีการระบาดใหญ่ในคนเมื่อปี 1977 ซึ่งยังอยู่ในทวีปเดิม\n— เคนยาและแทนซาเนียเป็นพื้นที่ระบาดดั้งเดิมในแอฟริกาตะวันออก ไม่ใช่พื้นที่นอกทวีป\n— อิรักและอิสราเอลไม่ใช่พื้นที่ที่เกิดการระบาดของ RVF ในปี 2000\n— จีนและไทยไม่มีการระบาดของ RVF ภายในประเทศ\n\n💡 RVF ข้ามออกนอกแอฟริกาครั้งแรกไปที่ซาอุดีอาระเบียกับเยเมน ในปี 2000",
