    "explain": "ผู้ติดเชื้อไข้เหลืองส่วนใหญ่มีอาการคล้ายไข้หวัดใหญ่ มีส่วนน้อยที่เข้าสู่ระยะรุนแรงซึ่งไวรัสทำลายเซลล์ตับ บิลิรูบินจึงคั่งจนเกิดดีซ่าน (jaundice) คือตัวเหลือง ตาเหลือง และปัสสาวะสีเข้ม อาการตัวเหลืองนี้คือที่มาของชื่อโรค และในระยะเดียวกันมีเลือดออกผิดปกติร่วมได้\n\n❌ ทำไมข้ออื่นผิด\n— ไข้เหลืองไม่ได้ทำให้เกิดผื่นสีเหลืองที่ผิวหนัง สีเหลืองมาจากบิลิรูบินที่คั่งเพราะตับถูกทำลาย\n— อาเจียนในระยะรุนแรงของไข้เหลืองเป็นเลือดสีคล้ำ ไม่ใช่สารสีเหลือง และไม่ใช่ที่มาของชื่อโรค\n— ตุ่มน้ำที่ฝ่ามือฝ่าเท้าไม่ใช่อาการของไข้เหลือง\n— เสมหะและอุจจาระสีเหลืองปนเลือดไม่ใช่อาการที่ใช้ตั้งชื่อโรค\n\n💡 เหลืองคือดีซ่าน จากตับที่ถูกไวรัสทำลายในระยะรุนแรง",
