    "q": "ข้อใดไม่ถูกต้องเกี่ยวกับโรค Crimean-Congo haemorrhagic fever (CCHF)",
    "options": [
      "เกิดจากไวรัสในสกุล Nairovirus โดยมีเห็บแข็ง (Ixodid ticks) เป็นพาหะหลัก",
      "มีไข้ ปวดศีรษะ คล้ายไข้หวัดใหญ่ รายรุนแรงมีเลือดออก อัตราตายราว 9 ถึง 50%",
      "ติดได้จากเห็บกัด การสัมผัสเลือดหรือเนื้อเยื่อสัตว์ติดเชื้อ และติดจากคนสู่คนได้",
      "สัตว์ป่าและสัตว์เลี้ยงหลายชนิด เช่น โค แพะ แกะ เป็นทั้งแหล่งอาหารของเห็บและ amplifying hosts",
      "มียาต้านไวรัสจำเพาะที่รักษาให้หายได้รวดเร็ว และมีวัคซีนในคนใช้อย่างแพร่หลาย"
    ],
    "answer": 4,
    "explain": "CCHF ยังไม่มียาต้านไวรัสจำเพาะที่รักษาให้หายได้ การรักษาหลักคือการประคับประคองตามอาการ และยังไม่มีวัคซีนที่ใช้แพร่หลายในคน การป้องกันจึงอยู่ที่การป้องกันเห็บกัดด้วยเสื้อผ้าแขนยาวขายาว การใส่ถุงมือและชุดป้องกันเมื่อสัมผัสเลือดหรือเนื้อเยื่อสัตว์ และการระวังการติดจากผู้ป่วย ส่วนข้อความอื่นถูกต้องทั้งหมด\n\n❌ ทำไมข้ออื่นผิด\n— CCHF เกิดจาก Nairovirus และมีเห็บแข็งเป็นพาหะจริง ข้อนี้ถูกต้อง\n— อาการเริ่มคล้ายไข้หวัดใหญ่ รายรุนแรงมีเลือดออก และอัตราตายอยู่ในช่วง 9 ถึง 50% ข้อนี้ถูกต้อง\n— เชื้อติดจากเห็บกัด จากเลือดหรือเนื้อเยื่อสัตว์ และติดจากคนสู่คนได้ เช่น บุคลากรที่ดูแลผู้ป่วย ข้อนี้ถูกต้อง\n— สัตว์ป่าและสัตว์เลี้ยงเป็นแหล่งอาหารของเห็บและเป็น amplifying hosts ข้อนี้ถูกต้อง\n\n💡 โรคไวรัสที่มียุงหรือเห็บเป็นพาหะในกลุ่มนี้ไม่มียารักษาจำเพาะ การป้องกันคือตัดทางติดต่อ",
    "source": "Zoonosis mid TJ เฉลย.pdf หน้า 10",
    "sourceType": "student-compilation",
    "verified": "Zoonosis mid TJ เฉลย.pdf น.10 ข้อ 12 (บล็อก Vector-borne ซึ่งหัวบล็อกไม่ระบุที่มา หน้าเดียวกับ Zoonosis Mid 86(1).pdf น.46 และ Zoonosis mid TJ ฝึกทำ.pdf น.10); โน้ต Zoonosis Mid 86(1).pdf น.7 (= Zoonosis Mid 86.pdf น.6) ไฮไลต์ ขีดเส้นใต้ และทำดาวที่ Hemorrhagic fever (sever case) ส่วน Treatment: No specific treatment อยู่หน้าเดียวกันโดยไม่มีเครื่องหมาย และหัวหน้า น.6 เขียนตัวแดงว่าทุกโรคในกลุ่มนี้ No specific treatment ทำได้แต่ supportive care; มุมหน้าจดไว้ว่าพาร์ทนี้เคยถามโรคละหนึ่งข้อ; ตรวจกับ u_cH2UtCIAg [43:44-46:11] (เห็บ อาการไข้และจุดเลือด กลุ่มเสี่ยงคือคนทำงานกับสัตว์) และส่วนเทียบสไลด์ของคลิปเดียวกัน (Treatment ไม่มีการรักษาจำเพาะ อัตราตาย 9-50%); เรื่องวัคซีนคลิปพูดไม่จบประโยค [45:56] ข้อความจึงยึดการรักษาที่ไม่มีจำเพาะเป็นหลัก ส่วนวัคซีนเป็นข้อเท็จจริงทั่วไปว่าไม่มีชนิดที่ใช้แพร่หลายในคน; การติดคนสู่คนมีใน notes-85-zoonoses zoo-vbz; 202012 กับ 107614 ครอบ Nairovirus เห็บแข็ง และเส้นทางติดต่อ; ไม่อยู่ในรายการข้อสอบ Vet 84 ที่ Zoonosis Mid 86(1).pdf น.36 จึงไม่ผูกกับกระดาษสอบ",
