    "answer": 3,
    "explain": "เชื้อกลุ่ม rickettsia เป็น obligate intracellular จึงเจริญบนอาหารเลี้ยงเชื้อที่ไม่มีเซลล์ไม่ได้ การวินิจฉัยเริ่มจากอาการร่วมกับประวัติสัมผัสพาหะหรือพื้นที่เสี่ยง แล้วยืนยันทางห้องปฏิบัติการด้วยการตรวจแอนติบอดี IgM และ IgG (serology) การตรวจ PCR และการแยกเชื้อในเซลล์เพาะเลี้ยง ในไข่ฟัก หรือโดยฉีดเข้าสัตว์ทดลอง\n\n❌ ทำไมข้ออื่นผิด\n— nutrient agar เป็นอาหารเลี้ยงเชื้อที่ไม่มีเซลล์ เชื้อที่ต้องอาศัยอยู่ในเซลล์จึงเจริญบนนั้นไม่ได้\n— การย้อม Gram จากเสมหะไม่ใช่วิธียืนยันเชื้อกลุ่มนี้ ซึ่งเล็กและอยู่ในเซลล์ วิธีตรวจหาตัวเชื้อที่ใช้คือ PCR\n— การทดสอบภูมิแพ้ทางผิวหนังไม่ใช้วินิจฉัยโรคกลุ่มนี้ วิธีตรวจแอนติบอดีที่ใช้คือ serology\n— serology อย่างเดียวไม่พอ ต้องอาศัยอาการและประวัติ และยืนยันด้วย PCR หรือการแยกเชื้อร่วมด้วย\n\n💡 เชื้อที่ต้องอยู่ในเซลล์ต้องเลี้ยงในสิ่งที่มีชีวิต คือเซลล์ ไข่ฟัก หรือสัตว์ทดลอง",
