    "answer": 0,
    "explain": "Ivermectin เป็นยากลุ่ม macrocyclic lactone ที่ใช้ป้องกันพยาธิฟิลาเรียในสัตว์เลี้ยง ออกฤทธิ์ฆ่าตัวอ่อน microfilaria และทำให้พยาธิตัวเมียที่โตเต็มวัยเป็นหมัน ยาในกลุ่มเดียวกันที่ใช้ได้คือ milbemycin oxime และ moxidectin ส่วน doxycycline ใช้ลดจำนวนแบคทีเรีย Wolbachia ที่อาศัยร่วมกับพยาธิ โดยให้ก่อนยาตัวอื่น เพื่อลดการเกิด immune complex ในอวัยวะสำคัญ เช่น ไต\n\n❌ ทำไมข้ออื่นผิด\n— Praziquantel ใช้กับพยาธิตัวตืดและพยาธิใบไม้ ไม่มีฤทธิ์ต่อพยาธิฟิลาเรีย\n— Pyrantel pamoate ใช้ถ่ายพยาธิตัวกลมในลำไส้ ไม่ออกฤทธิ์ต่อ microfilaria ในกระแสเลือด\n— Niclosamide ใช้กับพยาธิตัวตืดในลำไส้ และแทบไม่ถูกดูดซึมไปถึงพยาธิในกระแสเลือด\n— Metronidazole เป็นยาต้านโปรโตซัวและแบคทีเรียที่ไม่ใช้ออกซิเจน ไม่ใช่ยาถ่ายพยาธิ\n\n💡 พยาธิฟิลาเรียในสัตว์เลี้ยงควบคุมด้วยยากลุ่ม macrocyclic lactone ร่วมกับ doxycycline ที่ไปจัดการ Wolbachia",
