    "q": "จงอธิบายการดำเนินโรคของโรคพิษสุนัขบ้าในสัตว์ ตั้งแต่ได้รับเชื้อ ระยะฟักตัว ระยะแพร่เชื้อ จนถึงระยะแสดงอาการและการเสียชีวิต",
