    "model_answer": "ประเทศไทยควบคุมโรคพิษสุนัขบ้าภายใต้แนวคิด One Health ผ่านโครงการสัตว์ปลอดโรค คนปลอดภัย จากโรคพิษสุนัขบ้า โดยมีหน่วยงานหลักสามหน่วยคือ กรมปศุสัตว์ กรมควบคุมโรค และกรมส่งเสริมการปกครองท้องถิ่น ร่วมกับกรมประชาสัมพันธ์ มหาวิทยาลัย และองค์กรเอกชน เป้าหมายคือให้ประเทศปลอดโรคภายในปี 2573 สอดคล้องกับเป้าหมายระดับโลกที่จะกำจัดโรคพิษสุนัขบ้าที่แพร่โดยสุนัขให้หมดไปภายในปี 2030 มาตรการหลักมีดังนี้ หนึ่ง ฉีดวัคซีนสุนัขและแมวปีละ 2 รอบ คือช่วงปลายปีต่อต้นปีที่กรมปศุสัตว์ผลักดัน และช่วงกลางปีที่ท้องถิ่นทำ ให้ครอบคลุมมากกว่าร้อยละ 80 ของประชากร ซึ่งสูงกว่าเกณฑ์สากลร้อยละ 70 เพื่อเผื่อประชากรสัตว์ที่ปล่อยเลี้ยงและสัตว์จรที่สำรวจได้ไม่ครบ สอง ควบคุมประชากรสัตว์ด้วยการสำรวจ ขึ้นทะเบียน ทำหมัน และบริหารจัดการสุนัขและแมวไม่มีเจ้าของ สาม เฝ้าระวังโรคทั้งในคนและสัตว์ โดยผู้ป่วยไข้สมองอักเสบทุกรายต้องตรวจแยกโรคพิษสุนัขบ้า และองค์กรปกครองส่วนท้องถิ่นทุกแห่งต้องส่งตัวอย่างสัตว์ตรวจอย่างน้อยหนึ่งตัวอย่างจากการเฝ้าระวังเชิงรุกหรือเชิงรับ สี่ ตอบสนองอย่างรวดเร็วเมื่อพบโรค คือสอบสวนโรค ฉีดวัคซีนแบบวงแหวนรอบจุดเกิดโรค และประกาศเขตโรคระบาดสัตว์ชั่วคราวตามพระราชบัญญัติโรคระบาดสัตว์เพื่อควบคุมการเคลื่อนย้ายสัตว์ ห้า ประเมินและรับรองพื้นที่ปลอดโรคตามคู่มือการสร้างพื้นที่ปลอดโรค ซึ่งต้องผ่านเกณฑ์ด้านการเฝ้าระวัง การจัดการประชากรสัตว์ ความครอบคลุมวัคซีน และความยั่งยืนของการบูรณาการระหว่างหน่วยงาน หก ส่งเสริมบทบาทของเจ้าของสัตว์และประชาชน คือพาสัตว์ไปฉีดวัคซีน เลี้ยงไว้ในรั้วรอบขอบชิด ทำหมันถ้าไม่ต้องการลูก ไม่นำสัตว์ไปปล่อยทิ้ง และแจ้งเจ้าหน้าที่เมื่อมีสัตว์กัดกันหรือคนถูกกัด โดยให้ความรู้และประชาสัมพันธ์พร้อมวัดระดับความรู้ของชุมชน เจ็ด ป้องกันฝั่งคน คือสอนให้เลี่ยงการถูกสุนัขกัดตามคาถา 5 ย และให้ผู้ถูกกัดล้างแผลด้วยสบู่ กักสัตว์ไว้ดูอาการ แล้วไปรับวัคซีนหลังสัมผัสเชื้อ แปด ประสานกับประเทศเพื่อนบ้าน เพราะโรคแพร่ข้ามชายแดนได้",
    "explain": "นโยบายของไทยมีตัวเลขสองชุดที่ต้องแยกกัน คือเกณฑ์สากลที่ฉีดวัคซีนครอบคลุมมากกว่าร้อยละ 70 ก็ควบคุมโรคได้ กับเป้าของไทยที่มากกว่าร้อยละ 80 ซึ่งเป็นหลักเกณฑ์ของพื้นที่ปลอดโรคด้วย และพื้นที่ที่ไม่พบโรคยังไม่ถือว่าปลอดโรคจนกว่าจะผ่านการประเมินตามคู่มือ",
