    "explain": "HPAI คือไวรัสไข้หวัดนกที่ก่อโรครุนแรงและมีอัตราการตายสูงในสัตว์ปีก และพบได้เฉพาะในสับไทป์ H5 และ H7 เท่านั้น การจัดกลุ่มดูจากความรุนแรงในสัตว์ปีก ไม่ได้ดูจากความรุนแรงในคน สาย H5 ยังแบ่งย่อยเป็น clade และ clade 2.3.4.4b คือกลุ่มที่ระบาดต่อเนื่องไปหลายทวีป แตกเป็นหลายสับไทป์ เช่น H5N1 H5N5 H5N6 และ H5N8 และเป็นกลุ่มเดียวกับ H5N1 ที่ติดโคนมในสหรัฐอเมริกาปี 2024\n\n❌ ทำไมข้ออื่นผิด\n— HPAI รุนแรงที่สุดในสัตว์ปีก ไก่ฟาร์มอาจตายหมดโรงเรือนในวันเดียว\n— H5N1 ติดคนมาตั้งแต่ปี 1997 ที่ฮ่องกง และ H5N6 ก็ติดคนในจีน\n— H5 ระบาดไปถึงยุโรปและแอฟริกาตั้งแต่ปี 2004 และข้ามไปอเมริกาในปี 2014\n— HPAI มีได้เฉพาะ H5 และ H7 ส่วน H1N1 เป็นสับไทป์ของคนและสุกร\n\n💡 HPAI มีแค่ H5 กับ H7 และตัวที่ระบาดกว้างที่สุดตอนนี้คือ H5 clade 2.3.4.4b",
