    "explain": "เหตุการณ์ปี 2024 คือ H5N1 clade 2.3.4.4b จีโนไทป์ B3.13 กระโดดจากสัตว์ปีกเข้าสู่โคนม ไวรัสตัวนี้ยังชอบรีเซปเตอร์ α2,3 ของสัตว์ปีก แต่ติดเซลล์ที่มี α2,6 ได้ด้วยและมีการเปลี่ยนแปลงในยีน PB2 ที่ช่วยให้เพิ่มจำนวนในสัตว์เลี้ยงลูกด้วยนม ขณะที่เต้านมของโคมีรีเซปเตอร์ทั้งสองแบบ ไวรัสจึงเพิ่มจำนวนในเต้านมและออกมากับน้ำนม แพร่ต่อทั้งทางการสัมผัสใกล้ชิดและทางน้ำนม ไปถึงแมวที่กินนมดิบและสัตว์รอบฟาร์ม ฝั่งคนมีผู้ติดเชื้อ 72 ราย เสียชีวิต 2 ราย ส่วนใหญ่ติดจากโคนม\n\n❌ ทำไมข้ออื่นผิด\n— สุกรมีรีเซปเตอร์ทั้งสองแบบและเป็น mixing vessel แต่ไม่ใช่สัตว์ในเหตุการณ์นี้\n— ม้าเป็นโฮสต์ของ equine influenza H3N8 ซึ่งเป็นต้นทางของไข้หวัดสุนัข H3N8\n— แกะและแพะไม่ใช่ฝูงสัตว์ที่พบในเหตุการณ์ปี 2024\n— สุนัขจิ้งจอกเป็นสัตว์ป่า ไม่ใช่ปศุสัตว์ การติดเชื้อในสัตว์กินเนื้อเกิดประปรายจากการกินซาก\n\n💡 H5N1 ปี 2024 ในสหรัฐอเมริกา คือโคนม clade 2.3.4.4b จีโนไทป์ B3.13 และออกมากับน้ำนม",
