    "q": "การติดเชื้อไข้หวัดนก (avian influenza) ในมนุษย์มีช่องทางการแพร่หลักมาจากการรับประทานเนื้อสัตว์ดิบ",
    "answer": false,
    "explain": "❌ ผิด\n\nคนติดเชื้อไข้หวัดนกส่วนใหญ่จากการสัมผัสใกล้ชิดกับสัตว์ที่ติดเชื้อ สารคัดหลั่ง และสิ่งแวดล้อมที่ปนเปื้อน เช่น การเลือกและเชือดสัตว์ปีกมีชีวิตในตลาด การดูแลไก่ชนอย่างใกล้ชิดจนถึงดูดเสมหะออกจากปาก และการทำงานกับโคนมหรือฟาร์มสัตว์ปีกที่ติดเชื้อ ในเหตุการณ์ H5N1 ในโคนมของสหรัฐอเมริกา ผู้ป่วยส่วนใหญ่ติดจากโคนม รองลงมาคือจากฟาร์มสัตว์ปีก การกินเนื้อสัตว์จึงไม่ใช่ช่องทางหลักของคน แม้ยังควรกินเนื้อสัตว์ปีกและไข่ที่ปรุงสุกเสมอ\n\nจุดที่ต้องแยกคือสัตว์ตระกูลแมว เสือในฟาร์มของไทยและแมวบ้านติด H5N1 จากการกินไก่ดิบหรือซากสัตว์ปีกจริง และแมวในสหรัฐอเมริกาติดจากการกินนมดิบของโคที่ติดเชื้อ ช่องทางการกินจึงสำคัญในสัตว์กินเนื้อ แต่ไม่ใช่ช่องทางหลักของคน\n\n💡 คนติดจากการสัมผัส สัตว์ตระกูลแมวติดจากการกิน",
