    "answer": 1,
    "explain": "SARS เริ่มที่ประเทศจีนในเดือนพฤศจิกายน 2002 ผู้ป่วยรายแรกและผู้ป่วยกลุ่มแรกอยู่ในมณฑลกวางตุ้ง จากนั้นผู้ป่วยจากจีนไปพักโรงแรมในฮ่องกงและแพร่เชื้อให้แขกคนอื่น ผู้ที่ติดเชื้อจากโรงแรมนั้นเดินทางต่อไปไต้หวัน เวียดนาม สิงคโปร์ และแคนาดา รวมมีผู้ติดเชื้อใน 29 ประเทศ ต้นกำเนิดของไวรัสคือค้างคาว และมีชะมดในตลาดค้าสัตว์ป่าเป็น intermediate host\n\n❌ ทำไมข้ออื่นผิด\n— ฮานอยคือที่ที่ผู้ป่วยซึ่งติดเชื้อจากโรงแรมในฮ่องกงมารักษาตัว และเป็นจุดเริ่มการสอบสวนควบคุมโรค ไม่ใช่จุดกำเนิด\n— ยูนนานเป็นที่พบไวรัสค้างคาว RaTG13 ที่ใกล้เคียงกับ SARS-CoV-2 ไม่ใช่จุดเริ่มของ SARS\n— สิงคโปร์เป็นประเทศที่เชื้อแพร่ไปถึงภายหลัง\n— อู่ฮั่นเป็นจุดเริ่มของ COVID-19 ในปี 2019 ไม่ใช่ SARS ปี 2002\n\n💡 SARS ปี 2002 เริ่มที่กวางตุ้ง ส่วน COVID-19 ปี 2019 เริ่มที่อู่ฮั่น",
    "source": "Zoonosis Mid 86.pdf หน้า 9 และ Zoonosis mid TJ เฉลย.pdf หน้า 6",
