    "explain": "ผู้ติดเชื้อ Rift Valley fever ส่วนใหญ่ไม่มีอาการหรือมีไข้คล้ายไข้หวัดใหญ่ ส่วนน้อยมากเกิดรูปแบบรุนแรงซึ่งแยกได้สามแบบ คือโรคทางตา (ocular disease) เยื่อหุ้มสมองและสมองอักเสบ (meningoencephalitis) และไข้เลือดออก (haemorrhagic fever) ซึ่งเป็นแบบที่ทำให้เสียชีวิตได้ ต่างจากในสัตว์เคี้ยวเอื้องที่อาการเด่นคือแท้งและลูกสัตว์ตายสูง\n\n❌ ทำไมข้ออื่นผิด\n— อัมพาตและหูหนวกไม่ใช่รูปแบบรุนแรงของโรคนี้\n— ข้ออักเสบเรื้อรังและผื่นตุ่มน้ำไม่ใช่อาการของโรคนี้\n— โรคนี้ไม่ได้ทำให้ไตวายเรื้อรังหรือผิวหนังด่างขาว\n— อาการรุนแรงของโรคนี้ไม่ได้อยู่ที่ปอดและหัวใจ\n\n💡 RVF รุนแรงในคนมีสามแบบ คือ ตา สมอง และเลือดออก",
