    "answer": 2,
    "explain": "ไวรัสเจอีนำโดยยุงรำคาญ Culex วงจรหลักอยู่ระหว่างยุงกับนกและสุกรซึ่งเป็นตัวเพิ่มจำนวนเชื้อ (amplifying host) เมื่อยุงกัดสุกรที่มีเชื้อแล้วไปกัดคนหรือม้า คนและม้าจะป่วยได้แต่เป็นปลายทาง (dead-end host) ที่ไม่ส่งเชื้อต่อ พื้นที่เสี่ยงจึงอยู่รอบฟาร์มสุกร และการเฝ้าระวังเน้นที่สุกรกับม้า\n\n❌ ทำไมข้ออื่นผิด\n— Aedes เป็นพาหะของไข้เหลือง และสุนัขกับแมวไม่ใช่ตัวเพิ่มจำนวนเชื้อของเจอี\n— Anopheles เป็นพาหะของมาลาเรีย และโคกับกระบือไม่ได้ขยายเชื้อเจอี\n— ม้าเป็นปลายทางที่ป่วยได้แต่ไม่ขยายเชื้อ และริ้นดำไม่ใช่พาหะของโรคนี้\n— เห็บแข็งเป็นพาหะของ Crimean-Congo haemorrhagic fever และค้างคาวกินผลไม้เป็นแหล่งรังโรคของนิปาห์\n\n💡 เจอีมียุงรำคาญเป็นพาหะ ขยายเชื้อในสุกรกับนกน้ำ และจบที่คนกับม้า",
    "source": "Zoonosis Mid 86(1).pdf หน้า 36 และ Zoonosis mid TJ เฉลย.pdf หน้า 9",
    "sourceType": "student-compilation",
    "verified": "Zoonosis Mid 86(1).pdf หน้า 36 รายการข้อที่บันทึกหลังสอบของรุ่น Vet 84 (หัวกระดาษอยู่ที่ Zoonosis Mid 86(1).pdf หน้า 35) หัวข้อ vector-borne dz ข้อ \"JE พาหะคือ\" คำตอบ pig, culex, water bird และข้อ \"JE ติดโดยยุงอะไร\" คำตอบ culex สองข้อนี้เป็นข้อเท็จจริงชุดเดียวจึงรวมเป็นข้อเดียว ส่วนครึ่ง amplifier host ครอบอยู่แล้วใน 106096; ตัวเลือกเต็มจาก Zoonosis mid TJ เฉลย.pdf น.9 ข้อ 8 (บล็อก Vector-borne ซึ่งหัวบล็อกไม่ระบุที่มา) ซ้ำใน Zoonosis mid TJ ฝึกทำ.pdf น.9 และ Zoonosis Mid 86(1).pdf หน้า 45; บรรทัด Vector: Mosquitoes (Culex species) และหมูกับนกน้ำเป็น amplifier host อยู่ใน Zoonosis Mid 86.pdf หน้า 5 (= Zoonosis Mid 86(1).pdf หน้า 6); ตรวจกับ u_cH2UtCIAg [32:40-37:16] ได้แก่ [34:38-35:12] (นกและหมูเพิ่มจำนวนเชื้อ ม้าและคนเป็นปลายทาง) และ [36:53-36:59] (ยุงรำคาญ ฟาร์มหมู)",
