    "q": "โรคติดต่อจากสัตว์สู่คนที่เกิดจาก Nairovirus มีเห็บแข็ง (Ixodid ticks) เป็นพาหะ และพบในแอฟริกา ยุโรป ตะวันออกกลาง และเอเชีย ผู้ป่วยรายรุนแรงมีลักษณะเด่นตามข้อใด",
