    "answer": 1,
    "explain": "โรคนี้คือ Crimean-Congo haemorrhagic fever ผู้ป่วยเริ่มด้วยไข้ ปวดศีรษะ คล้ายไข้หวัดใหญ่ ในรายที่รุนแรงจะมีเลือดออกตามช่องเปิดของร่างกายและผิวหนัง ซึ่งเป็นที่มาของคำว่า haemorrhagic fever ในชื่อโรค อัตราตายอยู่ระหว่าง 9 ถึง 50% ยังไม่มีการรักษาจำเพาะ จึงรักษาตามอาการ และป้องกันด้วยการไม่ให้เห็บกัดกับใส่อุปกรณ์ป้องกันเมื่อสัมผัสเลือดหรือเนื้อเยื่อสัตว์ เพราะคนติดได้ทั้งจากเห็บ จากสัตว์ และจากผู้ป่วย\n\n❌ ทำไมข้ออื่นผิด\n— เกล็ดเลือดต่ำร่วมกับเม็ดเลือดขาวต่ำเป็นลักษณะเด่นของ SFTS ซึ่งนำโดยเห็บเช่นกัน\n— สมองอักเสบและความผิดปกติทางระบบประสาทที่เหลืออยู่เป็นภาพของไข้สมองอักเสบเจอีซึ่งนำโดยยุง\n— ดีซ่านและปัสสาวะสีเข้มเป็นที่มาของชื่อไข้เหลือง\n— โรคทางตาเป็นหนึ่งในรูปแบบรุนแรงของ Rift Valley fever ซึ่งนำโดยยุง\n\n💡 CCHF คือ Nairovirus จากเห็บแข็ง รายรุนแรงมีเลือดออกและตายได้ 9 ถึง 50%",
