    "year": 5,
    "type": "mcq",
    "examScope": "midterm",
    "q": "นอกเหนือจากการสัมผัสสุกรป่วยแล้ว มีรายงานการติดเชื้อไวรัสนิปาห์ (Nipah virus) ในคนจากการสัมผัสหรือบริโภคสิ่งใด",
    "options": [
      "การถูกยุงกัดในฟาร์มสุกร และการกินเนื้อไก่ที่ปรุงไม่สุก",
      "การถูกเห็บกัดขณะเดินป่า และการดื่มนมแพะที่ไม่ผ่านการฆ่าเชื้อ",
      "การสูดฝุ่นในคอกโค และการกินผักที่ปนเปื้อนปัสสาวะหนู",
      "การสัมผัสมูลนกป่า และการกินหอยน้ำจืดที่ปรุงไม่สุก",
      "การจับหรือกินเนื้อม้าที่ป่วย และการดื่มน้ำตาลปาล์มสดที่ไม่ต้ม"
    ],
    "answer": 4,
    "explain": "นอกจากการติดจากสุกรในการระบาดที่มาเลเซียและสิงคโปร์ ไวรัสนิปาห์มีเส้นทางสู่คนอีกสองแบบ แบบแรกที่ฟิลิปปินส์ปี 2014 คนติดจากการจับบังคับม้าที่ป่วยหรือกินเนื้อม้า โดยคาดว่าม้าได้รับเชื้อมาจากค้างคาว แล้วมีการติดจากคนสู่คนตามมาเล็กน้อย แบบที่สองที่บังกลาเทศและอินเดีย ค้างคาวแม่ไก่ (Pteropus) มากินและปัสสาวะใส่น้ำตาลปาล์มที่รองเก็บไว้ คนที่ดื่มน้ำตาลสดโดยไม่ผ่านความร้อนจึงติดเชื้อ แล้วแพร่ต่อไปยังคนใกล้ชิด การป้องกันจึงคิดจากเส้นทาง คือเลี่ยงการสัมผัสค้างคาว สุกร และม้าป่วย ใส่ชุดป้องกันเมื่อเลี่ยงไม่ได้ และต้มน้ำตาลสดก่อนดื่ม\n\n❌ ทำไมข้ออื่นผิด\n— ยุงเป็นพาหะของไข้สมองอักเสบเจอี โรคที่นิปาห์ถูกเข้าใจผิดว่าเป็นในช่วงแรก ส่วนไก่ไม่ใช่โฮสต์ของนิปาห์ ทั้งสองอย่างจึงไม่ใช่เส้นทางของนิปาห์\n— เห็บและนมแพะดิบเป็นเส้นทางของ Q fever และโรคแท้งติดต่อ (brucellosis)\n— ฝุ่นในคอกสัตว์และปัสสาวะหนูเป็นเส้นทางของ Q fever และ leptospirosis\n— มูลนกและหอยน้ำจืดดิบเป็นเส้นทางของเชื้อราและพยาธิ ไม่เกี่ยวกับนิปาห์\n\n💡 นิปาห์มีสามเส้นทาง คือสุกรที่มาเลเซีย ม้าที่ฟิลิปปินส์ และน้ำตาลปาล์มสดที่บังกลาเทศ",
    "source": "Zoonosis mid TJ เฉลย.pdf หน้า 14",
    "sourceType": "student-compilation",
    "verified": "Zoonosis mid TJ เฉลย.pdf น.14 ข้อ 4 ชุด Nipah virus (key ก: สัมผัสม้าและกินเนื้อม้าติดโรค รวมถึงดื่มน้ำตาลสด ซึ่งในชุดพิมพ์เพี้ยนเป็น น้ำตากเกล็ด/น้ำหมากสด); ถามซ้ำใน Zoonosis mid TJ ฝึกทำ.pdf น.14 (หน้าเดียวกันไม่มีเฉลย) และ Zoonosis Mid 86(1).pdf หน้า 50 (สำเนาหน้า TJ เดียวกัน); ประเด็นติดจากม้าได้เป็นตัวเลือกหนึ่งของข้อ Nipah ในกรอบรายการ Ebola & Nipah ของ Zoonosis Mid 86(1).pdf หน้า 5 (= Zoonosis Mid 86.pdf หน้า 4) ซึ่งเป็นสำเนารายการที่ Zoonosis Mid 86(1).pdf หน้า 35 ใต้หัวกระดาษข้อสอบที่ออกในปี 84 ข้อ Nipah นั้นถามภาพรวม (family, หมูเป็นพาหะ, อาการคล้าย JE, ติดจากม้าได้, ไม่มีวัคซีน) และเขียนเป็นอีกข้อจากหน้า 5 ข้อนี้จึงใช้ประเด็นเดียวกันแต่ไม่ใช่ข้อนั้นที่ออกซ้ำ; มุมหน้าจดว่า ตรงตามที่เน้นทำตัวสีๆ โดยในโน้ตหน้านั้น ม้าติดโรค เป็นตัวสีในบรรทัด \"มีเคสคนงานที่ดูแล/เชือดม้า และกินเนื้อม้าติดโรคด้วย\"; ตรวจกับ u_cH2UtCIAg [16:11-16:44] และ [19:36-20:04] (ม้า ฟิลิปปินส์ 2014) กับ [15:00-15:44] และ [20:04-20:15] (น้ำตาลปาล์มสด บังกลาเทศ) และ [20:45-21:07] (การป้องกัน); ทางน้ำตาลสดมีใน 107605 แล้ว ข้อนี้เติมทางผ่านม้า; ตัวลวงของ TJ สั้นและไม่สมจริงจนคำตอบยาวกว่าเกณฑ์ จึงเขียนตัวลวงใหม่เป็นเส้นทางของโรคอื่น",
