    "answer": 0,
    "explain": "ทั้งสี่โรคในตัวเลือกนี้มีรายงานในประเทศไทย ได้แก่ scrub typhus ซึ่งพบมากทางภาคเหนือ โดยเฉพาะหน้าฝนและช่วงที่คนเข้าป่า murine typhus ที่ติดทางอุจจาระหมัดและพบได้ทั้งในหนู แมว และสุนัข การติดเชื้อ Rickettsia felis ที่มีรายงานผู้ป่วยในไทยตั้งแต่ปี 2014 และพบเชื้อในแมวกับหมัดแมวในกรุงเทพฯ และ Q fever ที่มีรายงานผู้ป่วยแบบเรื้อรังซึ่งเป็นลิ้นหัวใจอักเสบ (endocarditis) ส่วน E. canis เป็นเชื้อของสุนัขที่ไม่ใช่สาเหตุของ ehrlichiosis ในคน รายงานทางการแพทย์พบการติดเชื้อในคนเพียงไม่กี่รายที่เวเนซุเอลา และไม่มีรายงานในไทย\n\n❌ ทำไมข้ออื่นผิด\n— ชุดที่มี Rocky Mountain spotted fever แทน Q fever ผิด เพราะ RMSF พบเฉพาะในทวีปอเมริกา และยังไม่พบเชื้อนี้ในไทย\n— ชุดที่มีการติดเชื้อ Ehrlichia canis ในคนแทน murine typhus ผิด เพราะยังไม่มีรายงาน E. canis ในคนในไทย ehrlichiosis ในคนเกิดจากเชื้อชนิดอื่นและพบหลักๆ ในทวีปอเมริกา\n— ชุดที่มี Rocky Mountain spotted fever แทน scrub typhus ผิด เพราะ RMSF ยังไม่พบในไทย ขณะที่ scrub typhus พบมาก\n— ชุดที่มีการติดเชื้อ Ehrlichia canis ในคนแทน Rickettsia felis ผิด เพราะยังไม่มีรายงาน E. canis ในคนในไทย\n\n💡 ในไทยมี scrub typhus, murine typhus, R. felis และ Q fever ส่วน RMSF ยังไม่พบ และ E. canis ในคนไม่มีรายงานในไทย",
