    "answer": 3,
    "explain": "พยาธิปากขอ (hookworm) ของสุนัขและแมวอยู่ในสกุล Ancylostoma และ Ancylostoma caninum เป็นพยาธิปากขอของสุนัขที่พบในประเทศไทย สัตว์ติดได้ทั้งจากการกินและจากตัวอ่อนระยะ L3 ไชผ่านผิวหนัง ซึ่งเป็นทางหลัก ลูกสัตว์ยังติดจากแม่ทางน้ำนมได้ ตัวเต็มวัยหลั่งสารยับยั้งการแข็งตัวของเลือดจนสัตว์เสียเลือดและขาดธาตุเหล็ก ส่วนในคน L3 ที่ไชผิวหนังทำให้เกิด creeping eruption และเด็กมักติดจากการเล่นกองดินกองทรายที่ปนเปื้อน\n\n❌ ทำไมข้ออื่นผิด\n— Ascaris lumbricoides เป็นพยาธิไส้เดือนของคน ไม่ใช่พยาธิปากขอของสุนัขและแมว\n— Enterobius vermicularis เป็นพยาธิเข็มหมุดของคน ไม่มีสุนัขหรือแมวเป็นโฮสต์\n— Trichuris trichiura เป็นพยาธิแส้ม้าของคนที่อาศัยในลำไส้ใหญ่ ไม่ใช่พยาธิปากขอ\n— Strongyloides stercoralis เป็นพยาธิเส้นด้าย ตัวอ่อนไชผิวหนังได้เช่นกันแต่ไม่ใช่พยาธิปากขอ\n\n💡 ปากขอของสุนัขและแมวคือสกุล Ancylostoma ส่วน lumbricoides, vermicularis และ trichiura เป็นพยาธิของคน",
