    "q": "พยาธิในข้อใดเป็นพยาธิติดต่อสู่คนที่มีรายงานเคสในแมวในประเทศไทยเป็นครั้งแรก",
    "options": [
      "Anatrichosoma sp.",
      "Ancylostoma ceylanicum",
      "Toxocara cati",
      "Dirofilaria immitis",
      "Brugia malayi"
    ],
    "answer": 0,
    "explain": "Anatrichosoma เป็นพยาธิตัวกลมที่ฝังตัวในชั้นผิวหนัง เคสในไทยเป็นแมวที่มีรอยโรคอักเสบที่อุ้งเท้า (pododermatitis) เพียงตัวเดียวในบ้านที่เลี้ยงแมว 4 ตัว ให้ยาปฏิชีวนะแล้วไม่ดีขึ้น เมื่อตัดชิ้นเนื้อจึงพบไข่ที่มีปลั๊กคล้ายไข่กลุ่ม Capillaria และพยาธิแส้ม้า แล้วยืนยันชนิดด้วยวิธีทางอณูชีววิทยา แมวหายภายใน 2 สัปดาห์หลังให้ยาถ่ายพยาธิกลุ่ม macrocyclic lactone และจนถึงปัจจุบันยังเป็นรายงานเคสเดียว\n\n❌ ทำไมข้ออื่นผิด\n— Ancylostoma ceylanicum เป็นพยาธิปากขอที่อาศัยในลำไส้ของสุนัขและแมว ไม่ใช่พยาธิในผิวหนังอุ้งเท้า\n— Toxocara cati เป็นพยาธิไส้เดือนของแมว ในคนตัวอ่อนเดินผิดที่ไปตามอวัยวะโดยคนเป็น paratenic host\n— Dirofilaria immitis เป็นพยาธิหนอนหัวใจที่มียุงเป็นพาหะ\n— Brugia malayi เป็นพยาธิฟิลาเรียที่มีแมวเป็นแหล่งรังโรคและทำให้เกิดโรคเท้าช้างในคน\n\n💡 แผลที่อุ้งเท้าแมวซึ่งยาปฏิชีวนะไม่ได้ผล ให้นึกถึง Anatrichosoma แล้วตัดชิ้นเนื้อตรวจ",
