    "verified": "Zoonosis mid TJ เฉลย.pdf น.25-26 ข้อ 13 (เฉลย ข. Anatrichosoma sp. ตัวเลือกห้าข้อชุดเดียวกัน สลับตำแหน่งคำตอบ; หัวบล็อก \"อ. ปิยนันท์ Parasitic zoonoses (Helminth)\" ไม่ได้ระบุที่มา ข้อ 1-19 เป็นชุดเดียวกับบันทึกหลังสอบ Vet 85); ถามซ้ำใน Zoonosis Mid 86.pdf น.13 ข้อ 13 (= Zoonosis Mid 86(1).pdf น.30; คำตอบ Anatricosomiasis ในหน้าที่มุมขวาบนจดหลังสอบว่า ตรง), ซูสุขติ mid น.13 ข้อ 13, Zoonosis Mid 86(1).pdf น.31 ข้อ 13, Zoonosis Mid 86(1).pdf น.61-62 (สำเนาหน้า TJ) และสรุป zoonosis (final) vet83 น.5 ข้อ 13 จึงเป็นข้อที่ถามซ้ำข้ามรุ่น; Zoonosis Mid 86(1).pdf น.33 ติดดาวและไฮไลต์ เคสแรกใน TH และติดดาวบทคัดย่อ first report of feline anatrichosomiasis in Thailand by pathological findings and molecular confirmation; ตรวจกับ gwgmq6oGOWc [49:59]-[52:34] (เคสแมวรายงานครั้งเดียว [50:11] แมว 1 ใน 4 ตัว [50:23] รอยโรคอุ้งเท้า [50:36] ยาปฏิชีวนะไม่ได้ผลจึง biopsy [50:48] ไข่มีปลั๊กกลุ่ม Capillaria และแส้ม้า [51:27]-[51:41] โมเลกุลระบุ Anatrichosoma [52:07] macrocyclic lactone หายใน 2 สัปดาห์ [52:21]) และ [54:11]-[56:08] สำหรับ Brugia malayi",
